import{_ as o,a as t,b as e}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.BCVHfIj7.js";import{_ as r,c as p,I as i,a7 as n,o as c}from"./chunks/framework.DGCt2JJv.js";import"./chunks/dayjs.min.DZyl58SH.js";const h="/long-press/assets/33f9ded0.BtMmIvvH.png",u="/long-press/assets/48bc4df4.DHTj35M6.png",d="/long-press/assets/ffb737d4.DOL54CnE.png",m="/long-press/assets/6436b540.CIOg93ff.png",_="/long-press/assets/fd2cb3a2.8Cy4EWCd.png",b="/long-press/assets/b43bb7d1.DR4gyTRW.png",g="/long-press/assets/8e516a0a.IVLoYugg.png",v="/long-press/assets/60fb597e.v53fOfTT.png",f="/long-press/assets/7016e423.FKPF8aGR.png",q="/long-press/assets/cb2ccac3.CBItC4nj.png",V="/long-press/assets/d83bb055.Rkjvv-SW.png",P="/long-press/assets/2d9716c0.BMBPtHi6.png",k="/long-press/assets/023338d4.oXPsMGFl.png",x="/long-press/assets/2e797e1a.YMTncqoQ.png",C="/long-press/assets/734f8d23.CGjP78jN.png",B="/long-press/assets/cee8f3ba.B_rK_zKt.png",F="/long-press/assets/ac9d1920.BQ23ndOu.png",T="/long-press/assets/7004e5f8.BxWBizfB.png",D="/long-press/assets/e6314c0c.DQt60cWk.png",A="/long-press/assets/0029e37b.Dde6mdBt.png",S="/long-press/assets/200f43bc.BqKGzAqN.png",I="/long-press/assets/7f87b453.CXLY3ycb.png",R="/long-press/assets/facdc5ce.CD6AcQk4.png",$="/long-press/assets/022493b9.BSy35VRF.png",j="/long-press/assets/c98902cf.HDFOLadX.png",G="/long-press/assets/879ac6f1.DSFiAGHF.png",N="/long-press/assets/49843fd5.Cnit76c4.png",Y=JSON.parse('{"title":"Viso画图技巧","description":"","frontmatter":{},"headers":[],"relativePath":"文档模板/visio画图.md","filePath":"文档模板/visio画图.md","lastUpdated":1722441511000}'),O={name:"文档模板/visio画图.md"},W=n('<h1 id="viso画图技巧" tabindex="-1">Viso画图技巧 <a class="header-anchor" href="#viso画图技巧" aria-label="Permalink to &quot;Viso画图技巧&quot;">​</a></h1><h2 id="多用组合" tabindex="-1">多用组合 <a class="header-anchor" href="#多用组合" aria-label="Permalink to &quot;多用组合&quot;">​</a></h2><h2 id="visio画完流程图如何快速优化排版" tabindex="-1">Visio画完流程图如何快速优化排版？ <a class="header-anchor" href="#visio画完流程图如何快速优化排版" aria-label="Permalink to &quot;Visio画完流程图如何快速优化排版？&quot;">​</a></h2><p>Visio优化排版总结：</p><p>1.水平居中每一列</p><p>2.组合每一列，全选之后横向分布</p><p>3.垂直居中每一行</p><p>4.组合每一行，全选之后纵向分布</p><p>:::</p><p>1 列对齐：选中第一列的矩形框-水平居中每一列</p><p>2 列间距对齐：将每一列的矩形框进行组合-位置-横向分布，实现了分布功能后记得取消组合</p><p>3 行对齐：选中每一行的矩形框-垂直居中每一行</p><p>4 行间距对齐：将每一行的矩形框进行组合-位置-纵向分布，实现了分布功能后记得取消组合</p><p>5 某个形状与某个形状的对齐（列对齐）：选中目标形状-选中源形状（多选）-水平居中</p><p>:::</p><h2 id="visio中如何批量修改形状大小" tabindex="-1">visio中如何批量修改形状大小？ <a class="header-anchor" href="#visio中如何批量修改形状大小" aria-label="Permalink to &quot;visio中如何批量修改形状大小？&quot;">​</a></h2><p>点击视图——任务窗格——大小和位置，就能找到修改大小的地方了 <img src="'+h+'" alt=""></p><h2 id="visio中-旋转形状注意事项" tabindex="-1">visio中，旋转形状注意事项 <a class="header-anchor" href="#visio中-旋转形状注意事项" aria-label="Permalink to &quot;visio中，旋转形状注意事项&quot;">​</a></h2><p>拖动鼠标拉远，就能更细致地调整旋转 <img src="'+u+'" alt=""></p><h2 id="高效排版-visio中如何快速对齐连接线" tabindex="-1">高效排版：visio中如何快速对齐连接线 <a class="header-anchor" href="#高效排版-visio中如何快速对齐连接线" aria-label="Permalink to &quot;高效排版：visio中如何快速对齐连接线&quot;">​</a></h2><ul><li>首先确保形状已经对齐</li><li>在设计菜单栏-版式-分隔和重叠选项</li><li>修改为 分隔无关线条，重叠相关线条</li><li>最后，选中没有变化的连接线</li><li>右键-重置连接线</li><li>再手动微调即可</li></ul><p><img src="'+d+'" alt="visio中如何快速对齐连接线"></p><h2 id="高效排版-如何让visio绘图变得更整齐" tabindex="-1">高效排版：如何让visio绘图变得更整齐？ <a class="header-anchor" href="#高效排版-如何让visio绘图变得更整齐" aria-label="Permalink to &quot;高效排版：如何让visio绘图变得更整齐？&quot;">​</a></h2><p>选中2个以上形状</p><ul><li>点击开始菜单栏-排列</li><li>可以通过左对齐、右对齐、上对齐、下对齐、水平居中、垂直居中、水平对齐、垂直对齐使形状对齐</li></ul><p>选中3个以上形状</p><ul><li>点击开始菜单栏-位置</li><li>可以通过横向分布或纵向分布使形状均匀等距分布</li></ul><p><img src="'+m+'" alt=""></p><h2 id="高效排版-visio中如何给连接线添加箭头" tabindex="-1">高效排版：Visio中如何给连接线添加箭头？ <a class="header-anchor" href="#高效排版-visio中如何给连接线添加箭头" aria-label="Permalink to &quot;高效排版：Visio中如何给连接线添加箭头？&quot;">​</a></h2><ul><li><p>首先确保连接线的方向一致且正确</p></li><li><p>创建连接线时，从起点到终点的方向，和整体是一致的</p></li><li><p>创建完一条连接线，创建第二条前，点击一下空白地方，取消上一个连接线的选择状态，防止出现拖动上一条连接线的失误</p></li><li><p>选中连接线</p></li><li><p>右键-设置形状格式</p></li><li><p>修改线条-末尾箭头类型和大小</p></li><li><p>在设计选项卡-主题中，一般使用第五个</p></li></ul><p><img src="'+_+'" alt=""></p><h2 id="高效排版-visio中如何调整连接线上文字的位置" tabindex="-1">高效排版：visio中如何调整连接线上文字的位置？ <a class="header-anchor" href="#高效排版-visio中如何调整连接线上文字的位置" aria-label="Permalink to &quot;高效排版：visio中如何调整连接线上文字的位置？&quot;">​</a></h2><ul><li><p>选中连接线上的文字</p></li><li><p>在功能区的开始选项卡-字体，修改字体样式，段落-修改排版</p></li><li><p>点击连接线</p></li><li><p>拖动小黄点可以修改文字位置</p></li><li><p>老版本文件没有小黄点</p></li><li><p>使用文本块工具-点击连接线-拖动文本框</p></li><li><p>推荐两种好看的排版方式</p><ul><li>垂直的流出线，可以把文字和连接线垂直居中</li><li>横向的连接线，可以把文字放在连接线的上方</li></ul></li></ul><p><img src="'+b+'" alt=""></p><h2 id="visio中-如何用格式刷批量改变形状样式" tabindex="-1">visio中，如何用格式刷批量改变形状样式 <a class="header-anchor" href="#visio中-如何用格式刷批量改变形状样式" aria-label="Permalink to &quot;visio中，如何用格式刷批量改变形状样式&quot;">​</a></h2><ul><li>选中一个形状，然后双击格式刷，这样格式刷可以多次使用</li><li>选中一个形状，点击格式化，然后用鼠标框选多个形状，可以快速批量一键修改样式</li><li>选中多个形状，点击格式刷，其他形状会和主控形状一个样式</li></ul><p><img src="'+g+'" alt=""></p><h2 id="visio中-如何设置统一的背景和水印" tabindex="-1">Visio中，如何设置统一的背景和水印？ <a class="header-anchor" href="#visio中-如何设置统一的背景和水印" aria-label="Permalink to &quot;Visio中，如何设置统一的背景和水印？&quot;">​</a></h2><ul><li><p>在设计功能区-背景选项卡-修改背景图案或添加标题模板</p></li><li><p>右键背景-设置形状格式-填充</p></li><li><p>右键-点击页面-页面设置</p></li><li><p>在弹窗中奖正常前景页的背景设置修改为引用刚才新建的背景页</p></li><li><p>还可以在背景页中添加文字、公司logo</p></li></ul><p><img src="'+v+'" alt=""></p><h2 id="visio中-如何修改连接线的跨线样式" tabindex="-1">Visio中，如何修改连接线的跨线样式？ <a class="header-anchor" href="#visio中-如何修改连接线的跨线样式" aria-label="Permalink to &quot;Visio中，如何修改连接线的跨线样式？&quot;">​</a></h2><ul><li>点击设计功能区-版式选项卡的右下角箭头</li><li>在弹窗中-布局与排列-找到跨线这一栏</li><li>将跨线添加到- 默认的水平线条</li><li>跨线样式建议使用-弧形或5个面</li><li>跨线的垂直大小和水平大小一般不需要改</li><li></li></ul><p><img src="'+f+'" alt=""></p><h2 id="visio中-微操形状用这4个技巧就够了-尤其是第3招" tabindex="-1">Visio中，微操形状用这4个技巧就够了，尤其是第3招 <a class="header-anchor" href="#visio中-微操形状用这4个技巧就够了-尤其是第3招" aria-label="Permalink to &quot;Visio中，微操形状用这4个技巧就够了，尤其是第3招&quot;">​</a></h2><ul><li>按住shift-用鼠标移动形状，可以限制形状只能在水平或垂直移动</li><li>选中一个形状后，按住shift+方向键，可以微调形状位置</li><li>按住Ctrl 选中一个形状，拖动到另一个位置松开鼠标，但不松开ctrl键，可以实现快速复制</li><li>按住shift-拖动边上的控制手柄，可以等比例改变形状的大小，拖动角上的控制手柄，可以非等比例改变形状的大小</li></ul><p><img src="'+q+'" alt=""></p><h2 id="visio中-如何在形状之外绑定连接线-连接点" tabindex="-1">Visio中，如何在形状之外绑定连接线？（连接点） <a class="header-anchor" href="#visio中-如何在形状之外绑定连接线-连接点" aria-label="Permalink to &quot;Visio中，如何在形状之外绑定连接线？（连接点）&quot;">​</a></h2><ul><li><p>开始选项卡-工具组-连接点工具</p></li><li><p>切换到连接点工具之后，先选中一个形状，会发现形状上有一些小黑点</p></li><li><p>连接线的端点可以固定在连接线上</p></li><li><p>按住Ctrl在形状外单击左键，就能创建一个新的连接点</p></li><li><p>或者选择一个连接点，拖动到形状外，就会在形状外创建一个连接点</p></li><li><p>用连接点工具，首先要选中一个形状，才能对形状上的连接点进行操作</p></li><li><p>选中连接点之后，按del可删除连接点</p></li></ul><p><img src="'+V+'" alt=""></p><h2 id="vision-快捷键" tabindex="-1">Vision 快捷键 <a class="header-anchor" href="#vision-快捷键" aria-label="Permalink to &quot;Vision  快捷键&quot;">​</a></h2><h3 id="visio中-画面大小怎么调-送你10组缩放快捷键" tabindex="-1">Visio中，画面大小怎么调？送你10组缩放快捷键 <a class="header-anchor" href="#visio中-画面大小怎么调-送你10组缩放快捷键" aria-label="Permalink to &quot;Visio中，画面大小怎么调？送你10组缩放快捷键&quot;">​</a></h3><p>如果你在选项设置-高级-编辑选项中，选中了用智能鼠标缩放，前面讲的前三个快捷键会变成：</p><p>鼠标滚轮-画面大小缩放</p><p>鼠标滚轮+ctrl-画面上下移动</p><p>鼠标滚轮+ctrl+shift-画面左右移动</p><p>另外在视图功能区-缩放，任务窗格-平铺和缩放中，还有更多关于缩放的选项。 <img src="'+P+'" alt=""></p><h3 id="vsio中-快捷键f4重复上一次操作" tabindex="-1">Vsio中，快捷键F4重复上一次操作 <a class="header-anchor" href="#vsio中-快捷键f4重复上一次操作" aria-label="Permalink to &quot;Vsio中，快捷键F4重复上一次操作&quot;">​</a></h3><p>Alt +F4</p><blockquote><p>笔记本电脑可能是fn+f4</p></blockquote><ul><li>重复上一次操作</li><li>快速创建新形状 <ul><li>先拖一个矩形</li><li>然后使用ctrl+鼠标单击拖动的方法，复制一个形状</li><li>再按F4，就会等距地复制出一个新形状</li></ul></li><li>重复对齐和分布功能 <ul><li>比如三行形状，都不太整齐</li><li>选中第一行，点击开始选项卡-对齐-垂直居中</li><li>再框选第二行，按F4，就会将其垂直居中</li></ul></li></ul><p><img src="'+k+'" alt=""></p><h3 id="visio中-使用shift键画出绝对水平或垂直的线条" tabindex="-1">Visio中，使用Shift键画出绝对水平或垂直的线条 <a class="header-anchor" href="#visio中-使用shift键画出绝对水平或垂直的线条" aria-label="Permalink to &quot;Visio中，使用Shift键画出绝对水平或垂直的线条&quot;">​</a></h3><ul><li>按住shift键，拖动鼠标，画出绝对水平或垂直的线条，也可画出45度的线</li><li>拖动一个已有线条的一个端点，同时按住shift,可以将线条改成水平或垂直</li><li>使用矩形或圆形工具时，按住shift键，可以画出正方形或正圆形</li><li>想要把已有形状修改为正比例的形状，可以在视图选项卡-任务窗格-打开大小和位置窗格-修改大小数值即可 <img src="'+x+'" alt=""></li></ul><h3 id="visio的4个复制粘贴小技巧-第3个超级好用" tabindex="-1">Visio的4个复制粘贴小技巧，第3个超级好用！ <a class="header-anchor" href="#visio的4个复制粘贴小技巧-第3个超级好用" aria-label="Permalink to &quot;Visio的4个复制粘贴小技巧，第3个超级好用！&quot;">​</a></h3><ul><li>Ctrl+D,直接复制粘贴，相当于Ctrl+C Ctrl+V的组合</li><li>直接复制粘贴会在右下角进行粘贴，若粘贴前在任意地方点一下，会在点击的位置粘贴</li><li>按住Ctrl，拖动形状，可以快速复制出一个形状，按住Ctrl+Shift，拖动形状，可以快速复制出水平或垂直对齐的形状</li><li>复制一个形状之后，每按一次F4，就会复制出一个新形状，而且这些形状是等距的</li></ul><p><img src="'+C+'" alt=""></p><h2 id="visio导出图片不清晰怎么办-修改这两个设置就可以" tabindex="-1">Visio导出图片不清晰怎么办？修改这两个设置就可以 <a class="header-anchor" href="#visio导出图片不清晰怎么办-修改这两个设置就可以" aria-label="Permalink to &quot;Visio导出图片不清晰怎么办？修改这两个设置就可以&quot;">​</a></h2><ul><li><p>按F12另存为，选择jpeg或者可移植网络图形，在弹窗中选择分辨率为打印机，大小设置为源</p></li><li><p>如果还不清晰，则自定义为更大的数值</p></li><li><p>想把部分形状导出为图片，先把这部分复制到PPT或者Word中，右键另存为图片即可</p></li><li><p>注意PPT里面积越大，导出的图片越大越清晰</p></li><li><p>png可以设置透明背景，visio另存为图片时，选择可移植网络图形，可以在设置对话框里选透明背景色</p></li></ul><blockquote><p>另存为pdf是最靠谱的，都是矢量图</p></blockquote><blockquote><p>插入到word里还是不清晰，word里点击文件，选项，高级，下面有一个不压缩图片质量选择高保真就好了 <img src="'+B+'" alt=""></p></blockquote><h2 id="想要熟练使用visio-这5种选择方式你得了解" tabindex="-1">想要熟练使用visio，这5种选择方式你得了解！ <a class="header-anchor" href="#想要熟练使用visio-这5种选择方式你得了解" aria-label="Permalink to &quot;想要熟练使用visio，这5种选择方式你得了解！&quot;">​</a></h2><ul><li>点选：左键单选，ctrl+左键多选，shift+左键多选</li><li>框选：长按数据左键拖动</li><li>套选：开始选项卡-选择-切换为套索选择，长按鼠标左键拖动，是曲线，曲线内的形状会被选中</li><li>全选：Ctrl+A</li><li>按类型选择：第二行比较有用，点形状角色，只勾选连接线，可选中所有连接线，然后批量修改格式</li></ul><p><img src="'+F+'" alt=""></p><h2 id="visio中-如何批量取消连接线的箭头" tabindex="-1">Visio中，如何批量取消连接线的箭头？ <a class="header-anchor" href="#visio中-如何批量取消连接线的箭头" aria-label="Permalink to &quot;Visio中，如何批量取消连接线的箭头？&quot;">​</a></h2><ul><li>开始选项卡-选择-按类型选择-形状角色-选择连接线</li><li>开始选项卡-形状样式-线条-箭头类型-改为无箭头</li><li>只有连接线工具画出的线才会被选中，线条工具画出的是不会被选中的！！！</li><li></li></ul><p><img src="'+T+'" alt=""></p><h2 id="visio中-如何给形状自动编号" tabindex="-1">Visio中，如何给形状自动编号？ <a class="header-anchor" href="#visio中-如何给形状自动编号" aria-label="Permalink to &quot;Visio中，如何给形状自动编号？&quot;">​</a></h2><ul><li><p>视图选项卡-加载项-其他Vision方案-给形状编号</p></li><li><p>一般选择手动编号</p></li><li><p>分配编号这里可以选择起始值，间隔值，前缀文字，前缀可手动输入</p></li><li><p>将形状放到页上时继续给形状编号，指的是新建形状后，会添加新的编号，一般可以勾选</p></li><li><p>高级-编号位置，可选择是在形状文字前还是后</p></li><li><p>手动编号设置完，点确定回到主界面</p></li><li><p>弹出手动编号对话框，每点一个形状就会对其编号</p></li></ul><p><img src="'+D+'" alt=""></p><h2 id="visio中-如何让绘图在画布上居中放置" tabindex="-1">Visio中，如何让绘图在画布上居中放置？ <a class="header-anchor" href="#visio中-如何让绘图在画布上居中放置" aria-label="Permalink to &quot;Visio中，如何让绘图在画布上居中放置？&quot;">​</a></h2><ul><li>画完图后，全选所有形状，组合为一个</li><li>新加一个矩形，拖动四条边线，使其与四周虚线框重合</li><li>选中参考矩形，置于底层，然后ctrl+D,选中组合，开始选项卡-对齐，选择水平对齐和居中对齐</li><li>最后删掉参考形状 <img src="'+A+'" alt=""></li></ul><h2 id="visio中-如何快速创建形状矩阵" tabindex="-1">Visio中，如何快速创建形状矩阵？ <a class="header-anchor" href="#visio中-如何快速创建形状矩阵" aria-label="Permalink to &quot;Visio中，如何快速创建形状矩阵？&quot;">​</a></h2><ul><li>创建一个形状</li><li>鼠标左键单击选中，然后点击视图选项卡-加载项-其他Visio方案-排列形状</li><li>输入横竖复制的个数，间距选项修改为形状边缘，再输入具体数值</li><li>设置完成，点击确认即可 <img src="'+S+'" alt=""></li></ul><h2 id="visio中如何自定义快捷键-【快速访问工具栏】" tabindex="-1">Visio中如何自定义快捷键？【快速访问工具栏】 <a class="header-anchor" href="#visio中如何自定义快捷键-【快速访问工具栏】" aria-label="Permalink to &quot;Visio中如何自定义快捷键？【快速访问工具栏】&quot;">​</a></h2><ul><li>点击选项对话框-自定义快速访问工具栏</li><li>右键点击快速访问工具栏，可以把工具栏放到功能区下方</li><li>按下Alt键，快速访问工具栏就出现了一堆灰底白字的快捷键提示，前九个，分别是Alt+1-9 <img src="'+I+'" alt=""></li></ul><h2 id="visio中-如何对齐连接点" tabindex="-1">Visio中，如何对齐连接点？ <a class="header-anchor" href="#visio中-如何对齐连接点" aria-label="Permalink to &quot;Visio中，如何对齐连接点？&quot;">​</a></h2><ul><li><p>在添加连接点之前，确保形状是对齐的</p></li><li><p>在想要添加连接点的位置，拖一条参考线，从画布左侧和上方的标尺处，点击鼠标左键拖动，可拉出参考线</p></li><li><p>再添加连接点，可以让连接点和参考线对齐</p></li><li><p>这样新建出来的连接点是对齐的，再拉连接线就会对齐。</p></li><li><p>最后点击参考线，删除即可</p></li><li><p>添加新的连接点：按Ctrl+Shift+1 切换到连接点工具，选中形状后，按Ctrl键单击鼠标，添加连接点</p></li></ul><p><img src="'+R+'" alt=""></p><h2 id="visio中-组合有什么用" tabindex="-1">Visio中，组合有什么用？ <a class="header-anchor" href="#visio中-组合有什么用" aria-label="Permalink to &quot;Visio中，组合有什么用？&quot;">​</a></h2><ul><li>组合的快捷键：ctrl+G</li><li>把多个形状单位绑定成一个单位，移动时统一移动，调整配色和文字样式时可以统一修改</li><li>固定形状，防止错乱</li><li>对齐</li><li>方便统一调整组合样式 <img src="'+$+'" alt=""></li></ul><h2 id="_99-的visio用户不知道的骚操作-新建窗口" tabindex="-1">99%的Visio用户不知道的骚操作：新建窗口 <a class="header-anchor" href="#_99-的visio用户不知道的骚操作-新建窗口" aria-label="Permalink to &quot;99%的Visio用户不知道的骚操作：新建窗口&quot;">​</a></h2><ul><li>visio 视图选项卡-窗口组-新建窗口</li><li>如果有一个大图，需要来回修改上半部分和下半部分内容，可以使用新建窗口，然后选择全部重排，这样就有两个操作界面</li><li>还可以左边打开第一页，右边打开第二页</li></ul><p><img src="'+j+'" alt=""></p><h2 id="visio中使用连接线的4个注意事项" tabindex="-1">Visio中使用连接线的4个注意事项 <a class="header-anchor" href="#visio中使用连接线的4个注意事项" aria-label="Permalink to &quot;Visio中使用连接线的4个注意事项&quot;">​</a></h2><ul><li>连接线两端一定要连接到形状上！！！</li><li>连接线是有方向的！！连接线的方向一定要和绘图的方向一致！！！</li><li>软件默认的连接线是折线，右键单击，可修改为曲线或直线；还可在设计选项卡的最右边，批量修改绘图例的连接线样式</li><li>设计选项卡-最右边右下角箭头-启用连接线拆分-可以直接把形状放到两个形状中间的连接线上，直接拆分插入 <img src="'+G+'" alt=""></li></ul><h2 id="visio中如何批量删除多个形状上的文字" tabindex="-1">Visio中如何批量删除多个形状上的文字？ <a class="header-anchor" href="#visio中如何批量删除多个形状上的文字" aria-label="Permalink to &quot;Visio中如何批量删除多个形状上的文字？&quot;">​</a></h2><ul><li>双击任意一个形状，进入文字编辑模式，Ctrl+A全选形状中的全部文字，按Del键删除</li><li>然后Ctrl+A全选，会选中一个空白占位符，Ctrl+C复制</li><li>框选其他所有形状，包括连接线，然后按Ctrl+V粘贴，可以批量把空白占位符，粘贴到所有形状上，实现批量删除效果</li></ul><p><img src="'+N+'" alt=""></p><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2>',99);function y(H,M,E,K,L,Q){const l=o,s=t,a=e;return c(),p("div",null,[W,i(l,{readTime:"10",words:"3.5k"}),i(s),i(a)])}const J=r(O,[["render",y]]);export{Y as __pageData,J as default};
